from rules import active_deps, is_acyclic


def solve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    best_score = None
    best_versions = None

    def domain(name, constraints):
        if name not in packages:
            return []
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        result = []
        for row in packages[name]:
            version = row["version"]
            if version in forbidden or (pin is not None and version != pin):
                continue
            if all(low <= version <= high for low, high in constraints.get(name, [])):
                result.append(row)
        return result

    def upper_bound(assigned, constraints):
        bound = []
        for name in names:
            if name in assigned:
                bound.append(assigned[name]["version"])
            elif name in constraints:
                rows = domain(name, constraints)
                if not rows:
                    return None
                bound.append(max(row["version"] for row in rows))
            else:
                rows = domain(name, {})
                bound.append(max([-1] + [row["version"] for row in rows]))
        return tuple(bound)

    def visit(assigned, constraints):
        nonlocal best_score, best_versions

        bound = upper_bound(assigned, constraints)
        if bound is None or (best_score is not None and bound <= best_score):
            return

        pending = [name for name in constraints if name not in assigned]
        if not pending:
            if not is_acyclic(assigned, features):
                return
            score = tuple(assigned[name]["version"] if name in assigned else -1 for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: assigned[name]["version"] for name in assigned}
            return

        choices = []
        for name in pending:
            rows = domain(name, constraints)
            if not rows:
                return
            choices.append((len(rows), name, rows))
        _, name, rows = min(choices, key=lambda item: (item[0], item[1]))
        rows = sorted(rows, key=lambda row: row["version"], reverse=True)

        for row in rows:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True
            for dep in active_deps(row, features):
                dep_name = dep["name"]
                next_constraints.setdefault(dep_name, []).append((dep["min"], dep["max"]))
                if dep_name in next_assigned:
                    version = next_assigned[dep_name]["version"]
                    if not all(low <= version <= high for low, high in next_constraints[dep_name]):
                        valid = False
                        break
            if valid:
                visit(next_assigned, next_constraints)

    initial_constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    visit({}, initial_constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def active_deps(row, features):
    result = []
    for dep in row.get("deps", []):
        feature = dep.get("feature")
        if feature and feature not in features:
            continue
        result.append(dep)
    return result


def is_acyclic(assigned, features):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dep in active_deps(assigned[name], features):
            target = dep["name"]
            if target not in assigned or not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in assigned)
